"""The rules factory (DECISIONS D58): rule targets generated by code from the law, read by two blind readers of different
families, recorded in the governance log; a rule settles only when the other family replicates the reading (D43).

    .venv/bin/python tools/rule_factory.py targets [--round N]   list the round's targets (no writing)
    .venv/bin/python tools/rule_factory.py prompts [--round N]   governance/readings/fabrica<N>/<rule>/prompt.json, fixed once written
    .venv/bin/python tools/rule_factory.py record [--round N]    propose or correct (leitor:a8) + blind review (leitor:b) -> log, rules/,
                                                                 FABRICA<N>.md

Round 2 (D60): the vocabulary grows by prazo_candidaturas_dias and data_envio_convite (read_rules round 8); its targets are
round 1's whose only gaps those values close, read again by both readers; a rule already in the log gets a correction.

Targets, round 1: the leaf passages of the CCP in force on 2026-10-01 that state, in their own words, a minimum number of
days for something to be done (prazo_minimo) or a value limit in euros (limiar) — the two rule types the engine evaluates
today. Articles already read by hand (19, 20, 135, 136: B3, D44-D51) are left out. The candidates are the passage's whole
article; the question asks for the rule the passage states. The readers' prompts and schemas are read_rules' (typed
conditions, round 3 on). A passage that states no such rule gives two readings that do not replicate: nothing settles.
"""
import argparse
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT)); sys.path.insert(0, str(ROOT / "tools"))
import read_rules as rr  # noqa: E402  (prompts, schemas, canonical readings, the rule builder)
from engine import rules as rules_mod  # noqa: E402
from engine import schema  # noqa: E402
from engine.governance import Log  # noqa: E402
from engine.sources import now_utc  # noqa: E402
from engine.store import Store, Writer  # noqa: E402

VERSION = "ccp-rule-factory-0.3"
TOOL = "ferramenta:rule-factory@3"  # D59 gap check, D60 round 2
FROUNDS = {1: {"round": "fabrica-1", "dir": rr.READINGS / "fabrica1", "rnd": 6, "closed": set(), "decision": "D58"},
           2: {"round": "fabrica-2", "dir": rr.READINGS / "fabrica2", "rnd": 8, "closed": {"candidaturas", "convite"}, "decision": "D60"}}
PROPOSER, PROPOSER_FILE = "leitor:a8", "leitor-a8.json"  # AMALIA + adapter v7 (D53), the best family-A reader when round 1 began
DATE = rr.NEW
HAND_READ = {"ccp:art19", "ccp:art20", "ccp:art135", "ccp:art136"}
PATTERNS = {
    "prazo_minimo": re.compile(r"prazo[^.;]{0,160}(n[aã]o pode ser inferior|m[ií]nimo de|inferior a)\s*\d+\s*dias", re.I),
    "limiar": re.compile(r"(inferior|superior|igual)[^.;]{0,30}(a|ao)\s*[\d .]+(?:,\d+)?\s*(€|euros)", re.I),
}
QUESTION = {
    "prazo_minimo": "Que prazo mínimo fixa a passagem {pid}: em que procedimento e condições, quantos dias, para que prazo e a contar "
                    "de quando? Dê as condições, os dias, o campo do prazo e de onde se conta.",
    "limiar": "Que limiar de valor fixa a passagem {pid}: para que procedimento e tipo de contrato, com que valor em euros e que "
              "comparação? Dê as condições e o limiar.",
}
TITLE = {"prazo_minimo": "Prazo mínimo fixado em {pid} (fábrica de regras, ronda {n})", "limiar": "Limiar de valor fixado em {pid} (fábrica de regras, ronda {n})"}
# D59: what the rule vocabulary cannot hold. Words of the passage, or of its article's heading, that name a deadline, an
# anchor, a procedure or a circumstance the schema has no value for. Two readers forced onto the nearest value can replicate
# each other and both be wrong (round 1: 4 of 4 settled readings were). Checked by code from the text; never by a model.
GAPS = [
    ("candidaturas", "prazo de candidaturas (o schema só tem prazo_propostas_dias)", re.compile(r"apresenta[çc][ãa]o (das |de )?candidaturas", re.I), "passage"),
    ("convite", "conta-se do envio do convite (o schema só tem anúncio)", re.compile(r"envio do convite", re.I), "passage"),
    ("urgencia", "urgência (sem campo no vocabulário)", re.compile(r"urg[êe]ncia", re.I), "passage"),
    ("procedimento", "procedimento fora do vocabulário (conceção, ideias, simplificado)", re.compile(r"concurso (de conce[çc][ãa]o|de ideias|simplificado)", re.I), "both"),
]


def gaps_of(store, pid, closed=()):
    """The GAPS the passage's own text, or (for procedures) its article's heading, shows, less those the round's vocabulary closed."""
    text = rr.version_at(store.current(pid), DATE)["text"]
    art = rr.version_at(store.current(pid.split(".")[0]), DATE)
    heading = "\n".join(art["text"].splitlines()[:2]) if art else ""
    return [name for key, name, pat, where in GAPS if key not in closed and (pat.search(text) or (where == "both" and pat.search(heading)))]


def slug_of(pid):
    return pid.split(":", 1)[1].replace(".", "-")


def targets(store, n=1):
    """Round 1: one target per leaf passage that states a minimum of days or a euro limit, outside the articles read by hand.
    Round n > 1: round 1's targets with a gap that round n's vocabulary closes entirely."""
    if n > 1:
        closed = FROUNDS[n]["closed"]
        return [{**t, "title": TITLE[t["type"]].format(pid=t["source_passage"], n=n)} for t in targets(store)
                if gaps_of(store, t["source_passage"]) and not gaps_of(store, t["source_passage"], closed)]
    hits = {}
    for p in store.objects["passagem"]:
        pid = p["id"]
        if not pid.startswith("ccp:art") or pid.split(".")[0] in HAND_READ:
            continue
        v = rr.version_at(store.current(pid), DATE)
        if not v:
            continue
        for type_, pat in PATTERNS.items():
            if pat.search(v["text"]) and (type_ != "limiar" or len(v["text"]) < 600):
                hits.setdefault(type_, set()).add(pid)
    out = []
    for type_, pids in sorted(hits.items()):
        leaves = sorted(p for p in pids if not any(o != p and o.startswith(p + ".") for o in pids))
        for pid in leaves:
            article = pid.split(".")[0]
            parts = sorted({q["id"] for q in store.objects["passagem"] if q["id"] == article or q["id"].startswith(article + ".")}
                           - {q["id"] for q in store.objects["passagem"] if not rr.version_at(store.current(q["id"]), DATE)})
            cands = [article] + [q for q in parts if q != article][:13]
            if pid not in cands:
                cands.append(pid)
            out.append({"rule": f"regra:ccp:auto-{type_.replace('_', '-')}-{slug_of(pid)}@v1", "type": type_, "norma": "norma:ccp",
                        "jurisdiction": "PT", "date": DATE, "title": TITLE[type_].format(pid=pid, n=1), "candidates": cands,
                        "question": QUESTION[type_].format(pid=pid), "source_passage": pid})
    return out


def cmd_prompts(store, n=1):
    R = FROUNDS[n]
    k = 0
    for t in targets(store, n):
        d = R["dir"] / rr.slug(t["rule"])
        d.mkdir(parents=True, exist_ok=True)
        if (d / "prompt.json").exists():
            continue  # a round's prompt is fixed once written: its answers are read against it
        body = {"rule": t["rule"], "type": t["type"], "date": t["date"], "candidates": t["candidates"], "prompt": rr.prompt_text(store, t, R["rnd"]),
                "schema": rr.schema_for(t, R["rnd"]), "round": R["round"], "source_passage": t["source_passage"]}
        (d / "prompt.json").write_text(json.dumps(body, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
        k += 1
    print(f"{k} new prompts in {R['dir']}")


def recorded_in(store, rule, rnd_name):
    return any(ev.get("assertion") == rule and (ev.get("payload") or {}).get("round") == rnd_name for _, ev in store.events)


def cmd_record(n=1):
    R = FROUNDS[n]
    store = Store([ROOT / "law", ROOT / "rules", ROOT / "governance"]).load()
    log = Log(ROOT / "governance")
    writer = Writer(ROOT / "rules", Store([ROOT / "rules"]).load())
    rows = []
    for t in targets(store, n):
        d = R["dir"] / rr.slug(t["rule"])
        ra, rb = [json.loads((d / f).read_text(encoding="utf-8")) if (d / f).exists() else None for f in (PROPOSER_FILE, "leitor-b.json")]
        a = rr.parse_answer(ra, t) if ra else None
        b = rr.parse_answer(rb, t) if rb else None
        row = {"rule": t["rule"], "type": t["type"], "a": a, "b": b, "state": None, "exact": None, "direction": None, "source": t["source_passage"],
               "gaps": gaps_of(store, t["source_passage"], R["closed"])}
        rows.append(row)
        known = log.replay().assertions.get(("regra", t["rule"]))
        if row["gaps"] and not known:
            row["state"] = "fora do vocabulário"  # D59: not proposed; the schema grows first
            continue
        if a is None or a["type"] != t["type"]:
            row["state"] = f"sem leitura válida de {PROPOSER}"
            continue
        if b is not None:
            row["exact"] = rr.same_reading(a, b)
            row["direction"] = rr.key_param(a) == rr.key_param(b)
        if recorded_in(store, t["rule"], R["round"]) or (known and row["gaps"]):
            row["state"] = log.replay().state_of("regra", t["rule"])  # recorded already in this round: answers are read once
            continue
        draft = rr.build_rule(store, t, a, a["passages"], [{"principal": PROPOSER, "family": "A", "at": ra["at"], "chosen_passages": a["passages"],
                                                            "blind": False, "evento": "evento:1"}], "proposed")
        problems = schema.validate("regra", draft)
        try:
            rules_mod.check(draft)
        except rules_mod.RuleError as exc:
            problems.append(str(exc))
        if problems:
            row["state"] = f"sem leitura válida de {PROPOSER}"
            row["why"] = str(problems[0])[:200]
            continue
        payload = {"chosen_passages": a["passages"], "conditions": a["conditions"], "params": a["params"], "answer_sha256": ra["sha256"], "round": R["round"]}
        if known:  # D60: a later round's reading is a new revision of the same rule
            ev_a = log.correct(PROPOSER, "regra", t["rule"], known["revision"], payload,
                               f"{R['decision']}: {R['round']}, read again with the wider vocabulary", ra["at"])
        else:
            ev_a = log.propose(PROPOSER, "regra", t["rule"], payload, ra["at"])
        rev = log.replay().assertions[("regra", t["rule"])]["revision"]
        readings = [{"principal": PROPOSER, "family": "A", "at": ra["at"], "chosen_passages": a["passages"], "blind": False, "evento": ev_a}]
        if b is not None:
            question = json.loads((d / "prompt.json").read_text(encoding="utf-8"))["prompt"].split("Pergunta: ", 1)[1]
            ev_b = log.review("leitor:b", "regra", t["rule"], rev, f"Blind, same prompt as {PROPOSER} ({R['round']}): {question}", "blind",
                              "uphold" if row["exact"] else "request_evidence", rb["at"],
                              payload={"chosen_passages": b["passages"], "conditions": b["conditions"], "params": b["params"],
                                       "answer_sha256": rb["sha256"], "round": R["round"]})
            readings.append({"principal": "leitor:b", "family": "B", "at": rb["at"], "chosen_passages": b["passages"], "blind": True, "evento": ev_b})
        row["state"] = log.replay().state_of("regra", t["rule"])
        rule = rr.build_rule(store, t, a, a["passages"], readings, row["state"])
        cur = writer.store.current(t["rule"])
        if cur is None:
            writer.append(rule)
        else:
            writer.revise(cur, {k: v for k, v in rule.items() if k not in ("id", "revision", "recorded_at", "supersedes")}, now_utc())
    invalidate_gaps(store, log, writer, rows)
    log.write_state()
    rr.write_packages(writer)
    write_report(rows, n)
    settled = sum(1 for r in rows if r["state"] == "settled")
    print(f"{len(rows)} targets, {settled} settled, {sum(1 for r in rows if r['exact'] is False)} differ, "
          f"{sum(1 for r in rows if str(r['state']).startswith('sem'))} without a valid proposal")


def invalidate_gaps(store, log, writer, rows):
    """D59: a factory rule settled on a passage with a vocabulary gap is invalidated (stale) by this tool, with the gap as reason."""
    for row in rows:
        if not row["gaps"] or log.replay().state_of("regra", row["rule"]) != "settled":
            continue
        reason = f"D59: a passagem {row['source']} diz o que o vocabulário das regras não tem: {'; '.join(row['gaps'])}. As duas leituras coincidem no valor mais próximo, que não é o da lei."
        log.invalidate(TOOL, "regra", row["rule"], reason, now_utc())
        writer.revise(writer.store.current(row["rule"]), {"state": "stale"}, now_utc())
        row["state"] = "stale"


INTRO = {
    1: ["Alvos gerados por código a partir do CCP em vigor a {date}: cada passagem-folha que fixa um número mínimo de dias ou um limite "
        "em euros, fora dos artigos lidos à mão (19.º, 20.º, 135.º, 136.º).",
        "D59: a passagem que diz o que o vocabulário das regras não tem (prazo de candidaturas, contagem desde o convite, urgência, "
        "procedimento fora do vocabulário) é marcada por código. Na ronda 1 as 4 leituras que ficaram settled eram todas destas: "
        "as duas famílias escolheram o valor mais próximo que o schema tinha. Foram invalidadas (stale) por esta ferramenta, "
        "com a razão no registo; o schema cresce antes da ronda 2."],
    2: ["D60: o vocabulário das regras ganha prazo_candidaturas_dias e data_envio_convite (o prompt diz o que cada campo quer dizer). "
        "Alvos: os da ronda 1 cujas únicas lacunas estes valores fecham. As duas famílias leem de novo às cegas; uma regra já no "
        "registo recebe uma correção (nova revisão), não uma segunda proposta.", ""],
}


def write_report(rows, n=1):
    R = FROUNDS[n]
    L = [f"# FÁBRICA DE REGRAS — ronda {n} (DECISIONS {R['decision']})", "",
         f"Gerado por tools/rule_factory.py ({VERSION}). " + INTRO[n][0].format(date=DATE) + f" Propõe {PROPOSER} "
         "(AMALIA + adaptador v7), leitor:b revê às cegas; só fica settled a leitura que leitor:b replica em forma canónica (D43).", "",
         INTRO[n][1], "",
         "| regra | passagem | estado | exato | direção | lacunas do vocabulário |", "|---|---|---|---|---|---|"]
    for r in rows:
        L.append(f"| {r['rule']} | {r['source']} | {r['state']}{' (' + r['why'] + ')' if r.get('why') else ''} | "
                 f"{'—' if r['exact'] is None else ('sim' if r['exact'] else 'não')} | {'—' if r['direction'] is None else ('sim' if r['direction'] else 'não')} | {'; '.join(r['gaps']) or '—'} |")
    L.append("")
    for r in rows:
        L += [f"## {r['rule']}", "", f"- {PROPOSER}: {rr.show(r['a'])}", f"- leitor:b: {rr.show(r['b'])}", ""]
    (R["dir"] / f"FABRICA{n}.md").write_text("\n".join(L).replace("\n\n\n", "\n\n") + "\n", encoding="utf-8")


def main():
    ap = argparse.ArgumentParser(); ap.add_argument("cmd", choices=["targets", "prompts", "record"]); ap.add_argument("--round", type=int, default=1, choices=sorted(FROUNDS))
    a = ap.parse_args()
    store = Store([ROOT / "law", ROOT / "rules", ROOT / "governance"]).load()
    if a.cmd == "targets":
        for t in targets(store, a.round):
            print(t["type"], t["source_passage"], len(t["candidates"]), t["rule"])
        return
    if a.cmd == "prompts":
        return cmd_prompts(store, a.round)
    cmd_record(a.round)


if __name__ == "__main__":
    main()
